'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Skeleton } from '@/registry/ndeko/ui/skeleton';

import {
  PERIODS,
  WORKSPACE,
  type MetricDefinition,
  type MetricId,
  type PeriodId,
} from './data';
import {
  chartPointsOf,
  csvRowsOf,
  figuresOf,
  formatMetric,
  metricOf,
  periodOf,
} from './figures';
import { MetricStrip } from './metric-strip';
import {
  ExportButton,
  PeriodSwitch,
  REPORT_SURFACE,
  ReportToolbar,
  downloadCsv,
  useSimulatedLoad,
  type PeriodOption,
} from './report-frame';
import { TrendChart } from './trend-chart';

const PERIOD_OPTIONS: PeriodOption<PeriodId>[] = PERIODS.map((period) => ({
  id: period.id,
  label: period.switchLabel,
}));

const SKELETON_CELLS = ['tracked', 'closed', 'billable', 'review'];

function periodKeyOf(periodId: PeriodId) {
  return periodId;
}

function peopleLabelOf(count: number) {
  if (count === 1) {
    return '1 person';
  }
  return `${count} people`;
}

function formatterOf(metric: MetricDefinition) {
  return (value: number) => formatMetric(metric, value);
}

function OverviewSkeleton() {
  return (
    <div
      aria-hidden='true'
      className={cn(REPORT_SURFACE, 'flex flex-col gap-6 p-2 pb-5')}
    >
      <div className='grid grid-cols-2 gap-1 lg:grid-cols-4'>
        {SKELETON_CELLS.map((cell) => (
          <div
            key={cell}
            className='flex flex-col gap-2 px-3 pt-2.5 pb-3.5 sm:px-4'
          >
            <Skeleton className='h-3 w-20' />
            <Skeleton className='h-5 w-16' />
            <Skeleton className='h-3 w-32' />
          </div>
        ))}
      </div>
      <div className='flex flex-col gap-3 px-3 sm:px-4'>
        <Skeleton className='h-3.5 w-40' />
        <Skeleton className='h-[224px] w-full rounded-lg' />
      </div>
    </div>
  );
}

export default function Dashboards01() {
  const load = useSimulatedLoad<PeriodId>('weeks', periodKeyOf);
  const [metricId, setMetricId] = useState<MetricId>('tracked');
  const shownPeriodId = load.loaded ?? load.requested;
  const shownPeriod = periodOf(shownPeriodId);
  const metric = metricOf(metricId);
  const figures = figuresOf(shownPeriodId);
  const points = chartPointsOf(shownPeriodId, metricId);
  const formatValue = formatterOf(metric);
  const chartTitle = `${metric.chartTitle} ${shownPeriod.perUnit}`;
  const peopleLabel = peopleLabelOf(WORKSPACE.peopleCount);
  const meta = `${shownPeriod.label} · ${peopleLabel}`;

  function exportOverview() {
    const rows = csvRowsOf(shownPeriodId);
    const fileName = `tidewell-overview-${shownPeriod.fileSlug}.csv`;
    downloadCsv(fileName, rows);
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <ReportToolbar title={WORKSPACE.name} meta={meta}>
        <ExportButton disabled={load.isFirstLoad} onExport={exportOverview} />
      </ReportToolbar>
      <div className='mx-auto flex w-full max-w-5xl flex-col gap-4 px-4 py-5 md:px-6'>
        <PeriodSwitch
          label='Period'
          options={PERIOD_OPTIONS}
          value={load.requested}
          isUpdating={load.isUpdating}
          onValueChange={load.request}
        />
        {load.isFirstLoad && <OverviewSkeleton />}
        {!load.isFirstLoad && (
          <section
            aria-label='Overview'
            aria-busy={load.isUpdating}
            className={cn(REPORT_SURFACE, 'flex flex-col gap-5 p-2 pb-5')}
          >
            <MetricStrip
              figures={figures}
              value={metricId}
              onValueChange={setMetricId}
            />
            <div className='flex flex-col gap-4 px-3 sm:px-4'>
              <div className='flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1'>
                <h2 className='text-sm font-medium'>{chartTitle}</h2>
                <span className='text-muted-foreground text-xs'>
                  Illustrative figures
                </span>
              </div>
              <TrendChart
                title={chartTitle}
                valueHeading={metric.label}
                points={points}
                formatValue={formatValue}
              />
            </div>
          </section>
        )}
      </div>
    </div>
  );
}

'use client';

import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';

import type { MetricId } from './data';
import type { MetricFigure } from './figures';
import { SlidingFigure } from './sliding-figure';

type MetricStripProps = {
  figures: MetricFigure[];
  value: MetricId;
  onValueChange: (metricId: MetricId) => void;
};

/** The figures band. Each cell is a tab that picks the figure the chart below draws. */
export function MetricStrip({
  figures,
  value,
  onValueChange,
}: MetricStripProps) {
  function changeValue(nextValue: unknown) {
    const figure = figures.find(
      (candidate) => candidate.metric.id === nextValue
    );
    if (figure) {
      onValueChange(figure.metric.id);
    }
  }

  return (
    <TabsPrimitive.Root value={value} onValueChange={changeValue}>
      <TabsPrimitive.List
        aria-label='Figure drawn in the chart'
        className='relative grid grid-cols-2 gap-1 lg:grid-cols-4'
      >
        {figures.map((figure) => (
          <TabsPrimitive.Tab
            key={figure.metric.id}
            value={figure.metric.id}
            className='group/metric hover:bg-foreground/[0.03] focus-visible:ring-ring/25 flex min-w-0 cursor-pointer flex-col items-start gap-1 rounded-lg px-3 pt-2.5 pb-3.5 text-left transition-colors duration-150 outline-none focus-visible:ring-[3px] sm:px-4'
          >
            <span className='text-muted-foreground group-data-active/metric:text-foreground text-xs font-medium transition-colors duration-150'>
              {figure.metric.label}
            </span>
            <SlidingFigure
              amount={figure.total}
              text={figure.totalText}
              className='text-lg leading-7 font-semibold'
            />
            <span className='text-muted-foreground text-xs text-pretty'>
              {figure.hint}
            </span>
          </TabsPrimitive.Tab>
        ))}
        <TabsPrimitive.Indicator className='bg-primary pointer-events-none absolute top-0 left-0 h-0.5 w-[calc(var(--active-tab-width)-1.5rem)] translate-x-[calc(var(--active-tab-left)+0.75rem)] translate-y-[calc(var(--active-tab-top)+var(--active-tab-height)-2px)] rounded-full transition-[translate,width] duration-300 ease-(--ease-out-quint) sm:w-[calc(var(--active-tab-width)-2rem)] sm:translate-x-[calc(var(--active-tab-left)+1rem)]' />
      </TabsPrimitive.List>
    </TabsPrimitive.Root>
  );
}

'use client';

import { motion, type Transition, useReducedMotion } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

import {
  ChartBubble,
  bubbleAlignOf,
  columnCenterOf,
  niceScale,
  percentOf,
  useActiveIndex,
} from './chart-kit';

const PLOT_HEIGHT = 200;

const VIEW_WIDTH = 1000;

const MAX_LINES = 4;

const PHONE_LABEL_STEP = 3;

const BUBBLE_GAP_PX = 10;

const MOVE_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

export type TrendPoint = {
  axisLabel: string;
  label: string;
  value: number;
};

type Coordinate = { x: number; y: number };

function moveTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE_TRANSITION;
}

function yOf(value: number, top: number) {
  const ratio = value / top;
  const height = ratio * PLOT_HEIGHT;
  return PLOT_HEIGHT - height;
}

function coordinatesOf(points: TrendPoint[], top: number): Coordinate[] {
  return points.map((point, index) => {
    const share = columnCenterOf(index, points.length);
    const x = share * VIEW_WIDTH;
    const y = yOf(point.value, top);
    return { x, y };
  });
}

function commandOf(coordinate: Coordinate, index: number) {
  const x = coordinate.x.toFixed(1);
  const y = coordinate.y.toFixed(1);
  if (index === 0) {
    return `M${x} ${y}`;
  }
  return `L${x} ${y}`;
}

function linePathOf(coordinates: Coordinate[]) {
  const commands = coordinates.map((coordinate, index) =>
    commandOf(coordinate, index)
  );
  return commands.join(' ');
}

function areaPathOf(coordinates: Coordinate[]) {
  const line = linePathOf(coordinates);
  const lastIndex = coordinates.length - 1;
  const first = coordinates[0];
  const last = coordinates[lastIndex];
  const firstX = first.x.toFixed(1);
  const lastX = last.x.toFixed(1);
  return `${line} L${lastX} ${PLOT_HEIGHT} L${firstX} ${PLOT_HEIGHT} Z`;
}

function leftOf(index: number, count: number) {
  const share = columnCenterOf(index, count);
  return percentOf(share);
}

function isPhoneLabel(index: number, count: number) {
  const isLast = index === count - 1;
  const isOnStep = index % PHONE_LABEL_STEP === 0;
  return isLast || isOnStep;
}

type TrendChartProps = {
  title: string;
  valueHeading: string;
  points: TrendPoint[];
  formatValue: (value: number) => string;
};

/** One series as a line over twelve columns. The line moves to its new shape when the data changes. */
export function TrendChart({
  title,
  valueHeading,
  points,
  formatValue,
}: TrendChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const transition = moveTransitionOf(shouldReduceMotion);
  const count = points.length;
  const lastIndex = count - 1;
  const values = points.map((point) => point.value);
  const maxValue = Math.max(...values);
  const scale = niceScale(maxValue, MAX_LINES);
  const coordinates = coordinatesOf(points, scale.top);
  const linePath = linePathOf(coordinates);
  const areaPath = areaPathOf(coordinates);
  const lastLeft = leftOf(lastIndex, count);
  const lastY = coordinates[lastIndex].y;
  const reading = useActiveIndex(count, lastIndex);
  const shownPoint = points[reading.shownIndex];
  const shownY = coordinates[reading.shownIndex].y;
  const shownLeft = leftOf(reading.shownIndex, count);
  const shownValue = formatValue(shownPoint.value);
  const readingText = `${shownPoint.label}: ${shownValue}`;
  const bubbleTop = shownY - BUBBLE_GAP_PX;
  const bubbleAlign = bubbleAlignOf(reading.shownIndex, count);
  const plotHeight = { height: PLOT_HEIGHT };

  return (
    <div className='flex flex-col'>
      <div className='grid grid-cols-[2.75rem_minmax(0,1fr)]'>
        <div aria-hidden='true' className='relative' style={plotHeight}>
          {scale.ticks.map((tick) => {
            const top = yOf(tick, scale.top);

            return (
              <span
                key={tick}
                className='text-muted-foreground absolute right-2.5 -translate-y-1/2 text-[11px] tabular-nums'
                style={{ top }}
              >
                {formatValue(tick)}
              </span>
            );
          })}
        </div>
        <div
          role='group'
          tabIndex={0}
          aria-label={`${title}. Use the arrow keys to read each value.`}
          className='focus-visible:ring-ring/25 relative touch-pan-y rounded-md outline-none focus-visible:ring-[3px]'
          style={plotHeight}
          {...reading.handlers}
        >
          <svg
            aria-hidden='true'
            viewBox={`0 0 ${VIEW_WIDTH} ${PLOT_HEIGHT}`}
            preserveAspectRatio='none'
            className='absolute inset-0 size-full overflow-visible'
          >
            {scale.ticks.map((tick) => {
              const y = yOf(tick, scale.top);

              return (
                <line
                  key={tick}
                  x1={0}
                  x2={VIEW_WIDTH}
                  y1={y}
                  y2={y}
                  strokeWidth={1}
                  vectorEffect='non-scaling-stroke'
                  className='stroke-border'
                />
              );
            })}
            <motion.path
              initial={false}
              animate={{ d: areaPath }}
              transition={transition}
              className='fill-primary/[0.08]'
            />
            <motion.path
              initial={false}
              animate={{ d: linePath }}
              transition={transition}
              fill='none'
              strokeWidth={2}
              strokeLinecap='round'
              strokeLinejoin='round'
              vectorEffect='non-scaling-stroke'
              className='stroke-primary'
            />
          </svg>
          {reading.isActive && (
            <span
              aria-hidden='true'
              className='bg-foreground/15 pointer-events-none absolute inset-y-0 w-px'
              style={{ left: shownLeft }}
            />
          )}
          <motion.span
            aria-hidden='true'
            initial={false}
            animate={{ y: lastY }}
            transition={transition}
            className='bg-primary ring-card pointer-events-none absolute top-0 size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2'
            style={{ left: lastLeft }}
          />
          {reading.isActive && (
            <span
              aria-hidden='true'
              className='bg-card ring-primary pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2'
              style={{ left: shownLeft, top: shownY }}
            />
          )}
          <ChartBubble
            left={shownLeft}
            top={bubbleTop}
            align={bubbleAlign}
            isVisible={reading.isActive}
          >
            <span className='text-muted-foreground'>{shownPoint.label}</span>
            <span className='text-[13px] font-medium tabular-nums'>
              {shownValue}
            </span>
          </ChartBubble>
        </div>
        <span aria-hidden='true' />
        <div aria-hidden='true' className='relative mt-2 h-4'>
          {points.map((point, index) => {
            const left = leftOf(index, count);
            const isShownOnPhone = isPhoneLabel(index, count);
            const isLast = index === lastIndex;

            return (
              <span
                key={point.label}
                className={cn(
                  'text-muted-foreground absolute top-0 -translate-x-1/2 text-[11px] whitespace-nowrap tabular-nums',
                  !isShownOnPhone && 'hidden sm:block',
                  isLast && 'text-foreground font-medium'
                )}
                style={{ left }}
              >
                {point.axisLabel}
              </span>
            );
          })}
        </div>
      </div>
      <span aria-live='polite' className='sr-only'>
        {reading.isReadingByKeys && readingText}
      </span>
      <table className='sr-only'>
        <caption>{title}</caption>
        <thead>
          <tr>
            <th scope='col'>Period</th>
            <th scope='col'>{valueHeading}</th>
          </tr>
        </thead>
        <tbody>
          {points.map((point) => (
            <tr key={point.label}>
              <th scope='row'>{point.label}</th>
              <td>{formatValue(point.value)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

const NICE_FACTORS = [1, 2, 5, 10];

export function niceScale(maxValue: number, maxLines: number) {
  const safeMax = Math.max(maxValue, 1);
  const roughStep = safeMax / maxLines;
  const logarithm = Math.log10(roughStep);
  const exponent = Math.floor(logarithm);
  const magnitude = 10 ** exponent;
  const factor = NICE_FACTORS.find((candidate) => {
    const candidateStep = candidate * magnitude;
    return candidateStep >= roughStep;
  });
  const safeFactor = factor ?? 10;
  const step = safeFactor * magnitude;
  const lineCount = Math.ceil(safeMax / step);
  const top = lineCount * step;
  const tickCount = lineCount + 1;
  const ticks = Array.from({ length: tickCount }, (_, index) => {
    return index * step;
  });
  return { top, ticks };
}

export function columnCenterOf(index: number, count: number) {
  const center = index + 0.5;
  return center / count;
}

export function percentOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

function columnIndexAt(event: React.PointerEvent<HTMLElement>, count: number) {
  const box = event.currentTarget.getBoundingClientRect();
  const offset = event.clientX - box.left;
  const share = offset / box.width;
  const rawIndex = Math.floor(share * count);
  const lastIndex = count - 1;
  const clampedHigh = Math.min(rawIndex, lastIndex);
  return Math.max(clampedHigh, 0);
}

function steppedIndexOf(key: string, current: number, count: number) {
  const lastIndex = count - 1;
  if (key === 'ArrowRight') {
    const next = current + 1;
    return Math.min(next, lastIndex);
  }
  if (key === 'ArrowLeft') {
    const previous = current - 1;
    return Math.max(previous, 0);
  }
  if (key === 'Home') {
    return 0;
  }
  if (key === 'End') {
    return lastIndex;
  }
  return null;
}

/**
 * One reading position for a chart: the pointer column wins while it is over the plot,
 * the arrow keys move it while the plot has keyboard focus.
 */
export function useActiveIndex(count: number, defaultIndex: number) {
  const [pointerIndex, setPointerIndex] = useState<number | null>(null);
  const [keyIndex, setKeyIndex] = useState<number | null>(null);
  const [lastIndex, setLastIndex] = useState(defaultIndex);
  const activeIndex = pointerIndex ?? keyIndex;
  const isActive = activeIndex !== null;
  const isReadingByKeys = keyIndex !== null;
  const wantedIndex = activeIndex ?? lastIndex;
  const lastColumn = count - 1;
  const highestIndex = Math.max(lastColumn, 0);
  const shownIndex = Math.min(wantedIndex, highestIndex);

  function pointAt(event: React.PointerEvent<HTMLElement>) {
    const index = columnIndexAt(event, count);
    setPointerIndex(index);
    setLastIndex(index);
  }

  function leave(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType === 'mouse') {
      setPointerIndex(null);
    }
  }

  function focus(event: React.FocusEvent<HTMLElement>) {
    const isKeyboardFocus = event.currentTarget.matches(':focus-visible');
    if (isKeyboardFocus) {
      setKeyIndex(lastIndex);
    }
  }

  function blur() {
    setKeyIndex(null);
    setPointerIndex(null);
  }

  function step(event: React.KeyboardEvent<HTMLElement>) {
    if (event.key === 'Escape') {
      setKeyIndex(null);
      return;
    }
    const current = keyIndex ?? lastIndex;
    const next = steppedIndexOf(event.key, current, count);
    if (next === null) {
      return;
    }
    event.preventDefault();
    setPointerIndex(null);
    setKeyIndex(next);
    setLastIndex(next);
  }

  const handlers = {
    onPointerMove: pointAt,
    onPointerDown: pointAt,
    onPointerLeave: leave,
    onFocus: focus,
    onBlur: blur,
    onKeyDown: step,
  };

  return { shownIndex, isActive, isReadingByKeys, handlers };
}

type BubbleAlign = 'start' | 'center' | 'end';

const BUBBLE_ALIGN: Record<BubbleAlign, string> = {
  start: '-translate-x-3',
  center: '-translate-x-1/2',
  end: '-translate-x-[calc(100%-0.75rem)]',
};

export function bubbleAlignOf(index: number, count: number): BubbleAlign {
  if (index === 0) {
    return 'start';
  }
  const isLast = index === count - 1;
  if (isLast) {
    return 'end';
  }
  return 'center';
}

type ChartBubbleProps = {
  left: string;
  top: number;
  align: BubbleAlign;
  isVisible: boolean;
  children: React.ReactNode;
};

/** The one value bubble of a chart. It stays mounted so it can fade out where it was. */
export function ChartBubble({
  left,
  top,
  align,
  isVisible,
  children,
}: ChartBubbleProps) {
  const position = { left, top };

  return (
    <div
      aria-hidden='true'
      className='pointer-events-none absolute z-10'
      style={position}
    >
      <div
        className={cn(
          'surface-raised flex -translate-y-full flex-col gap-0.5 rounded-lg px-2.5 py-1.5 text-xs whitespace-nowrap',
          'origin-bottom transition-[opacity,scale] duration-[125ms] ease-(--ease-out-strong)',
          BUBBLE_ALIGN[align],
          !isVisible && 'scale-[0.97] opacity-0'
        )}
      >
        {children}
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useState } from 'react';

import {
  CheckIcon,
  DownloadIcon,
  LoaderCircleIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

export const REPORT_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const FIRST_LOAD_MS = 900;

const UPDATE_MS = 450;

const EXPORTED_NOTICE_MS = 1600;

const FORMULA_PREFIXES = ['=', '+', '-', '@'];

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const NOTE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const NOTE_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const NOTE_VARIANTS: Variants = {
  enter: { opacity: 0, x: -4 },
  visible: { opacity: 1, x: 0, transition: NOTE_IN },
  exit: { opacity: 0, transition: NOTE_OUT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: NOTE_IN },
  exit: { opacity: 0, transition: NOTE_OUT },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function noteVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return NOTE_VARIANTS;
}

function loadDelayOf(isFirstLoad: boolean) {
  if (isFirstLoad) {
    return FIRST_LOAD_MS;
  }
  return UPDATE_MS;
}

function loadedKeyOf<Query>(
  loaded: Query | null,
  keyOf: (query: Query) => string
) {
  if (loaded === null) {
    return null;
  }
  return keyOf(loaded);
}

/**
 * Stands in for a request: the first load shows a skeleton, a later change keeps the
 * previous result on screen until the next one arrives.
 */
export function useSimulatedLoad<Query>(
  initialQuery: Query,
  keyOf: (query: Query) => string
) {
  const [requested, setRequested] = useState(initialQuery);
  const [loaded, setLoaded] = useState<Query | null>(null);
  const isFirstLoad = loaded === null;
  const delay = loadDelayOf(isFirstLoad);
  const requestedKey = keyOf(requested);
  const loadedKey = loadedKeyOf(loaded, keyOf);
  const isUpdating = loadedKey !== null && loadedKey !== requestedKey;

  useEffect(() => {
    const timer = window.setTimeout(() => setLoaded(requested), delay);
    return () => window.clearTimeout(timer);
  }, [requested, delay]);

  return { requested, loaded, isFirstLoad, isUpdating, request: setRequested };
}

export type PeriodOption<Id extends string> = { id: Id; label: string };

type ReportToolbarProps = {
  title: string;
  meta: string;
  children?: React.ReactNode;
};

export function ReportToolbar({ title, meta, children }: ReportToolbarProps) {
  return (
    <div className='hairline-b border-border flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3 md:px-6'>
      <div className='flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-0.5'>
        <h1 className='truncate text-lg font-semibold text-balance'>{title}</h1>
        <span className='text-muted-foreground text-xs tabular-nums'>
          {meta}
        </span>
      </div>
